# Source for q/ae-anatphys2.js: Anatomy and Physiology (second batch).
AN="Anatomy"; PH="Physiology"
Q=[
# --- LV segments and coronary territories ---
(AN,"The six basal LV segments in the ASE model are:","Anterior, anteroseptal, inferoseptal, inferior, inferolateral and anterolateral",["Septal, lateral, anterior, inferior, apical and posterior","Six apical segments","Basal, mid, apical, cap, septum and free wall"],"The mid level uses the same six names; the apical level has four plus the apical cap.","F"),
(AN,"The four apical LV segments are:","Apical anterior, apical septal, apical inferior and apical lateral",["Apical anteroseptal and inferolateral only","Six segments like the base","Apical cap only"],"The apex is narrower, so it is divided into four segments.","F"),
(AN,"The basal inferolateral segment is usually supplied by the:","Left circumflex artery",["Left anterior descending artery","Right coronary only in all hearts","Left main only"],"In right-dominant hearts, the RCA may also supply part of it.","F"),
(AN,"The mid anteroseptal segment is usually supplied by the:","Left anterior descending artery",["Right coronary artery","Left circumflex artery","Posterior descending artery"],"The anterior septum is fed by septal perforators from the LAD.","F"),
(AN,"The basal inferior segment is usually supplied by the:","Right coronary artery (via the PDA in right-dominant hearts)",["Left anterior descending","Diagonal branch","Obtuse marginal only"],"Inferior wall motion abnormalities point to RCA disease.","F"),
(AN,"The apical segments are most often supplied by the:","Left anterior descending artery, which often wraps around the apex",["Right coronary artery only","Left circumflex only","Coronary sinus"],"A 'wraparound' LAD can supply the apical inferior wall too.","F"),
# --- Coronary veins ---
(AN,"The great cardiac vein runs alongside the:","Left anterior descending artery, then the circumflex, draining into the coronary sinus",["Right coronary artery","Posterior descending artery","Pulmonary artery"],"The middle cardiac vein runs with the posterior descending artery.","C"),
(AN,"Thebesian veins are:","Small veins that drain the heart muscle directly into the chambers",["Large epicardial veins","Pulmonary veins","Veins of the pericardium only"],"They return a small part of coronary venous blood.","C"),
# --- Myocardial fiber architecture ---
(AN,"The fibers of the LV wall are arranged so that:","Subendocardial and subepicardial fibers run longitudinally in opposite helices, and mid-wall fibers run circumferentially",["All fibers run in one direction","Only circumferential fibers exist","Fibers are arranged randomly"],"This helical arrangement produces shortening, thickening and twisting.","C"),
(PH,"LV twist (torsion) during systole refers to:","The base rotating clockwise and the apex counterclockwise when viewed from the apex",["Both rotating the same way","No rotation at all","Only the RV rotating"],"Untwisting in early diastole helps suction blood into the LV.","C"),
(PH,"The subendocardial layer is most vulnerable to ischemia because:","It is furthest from the epicardial coronaries and is compressed most in systole",["It has the most blood supply","It is outside the heart","It has no muscle"],"Longitudinal strain, which reflects subendocardial fibers, often falls first.","C"),
# --- RV anatomy ---
(AN,"The three parts of the right ventricle are:","Inflow, apical trabecular and outflow (infundibulum)",["Base, mid and apex like the LV","Septal, lateral and posterior","Only inflow and outflow"],"Its complex crescent shape is why RV volumes are hard to measure in 2D.","F"),
(AN,"The crista supraventricularis is a muscular ridge that:","Separates the RV inflow from the RV outflow",["Divides the LA","Forms the mitral annulus","Is part of the aorta"],"It lies between the tricuspid and pulmonic valves.","C"),
(AN,"The septomarginal trabecula is another name for the:","Moderator band",["Crista terminalis","Chiari network","Eustachian valve"],"It carries part of the right bundle branch to the anterior papillary muscle.","F"),
(AN,"Compared with the mitral valve, the tricuspid valve has:","A larger annulus and attachments to the septum",["A smaller annulus","No chordae","Only two leaflets"],"The tricuspid annulus is the largest of the four valves.","F"),
(AN,"The RV is normally shaped like a:","Crescent wrapped around the LV",["Bullet","Sphere","Cube"],"It looks triangular in the A4C and crescent-shaped in short axis.","F"),
# --- Mitral apparatus ---
(AN,"The mitral valve apparatus includes the annulus, leaflets, chordae, papillary muscles and:","The LV wall",["The aortic root only","The pulmonary veins","The coronary sinus"],"Problems in any part can cause MR, such as LV dilation in secondary MR.","F"),
(AN,"Primary (first-order) chordae attach to the:","Free edges of the mitral leaflets",["Annulus","Base of the leaflets only","Aortic valve"],"Rupture of primary chordae causes a flail leaflet.","C"),
(AN,"The mitral annulus normally has a:","Saddle (hyperbolic paraboloid) shape",["Flat circular shape","Square shape","Triangular shape"],"This is why prolapse is judged in the parasternal long-axis view.","F"),
# --- Aortic root and great vessels ---
(AN,"The aortic root includes:","The annulus, sinuses of Valsalva, cusps and sinotubular junction",["The aortic arch and descending aorta","Only the annulus","The pulmonary artery"],"The ascending aorta begins above the sinotubular junction.","F"),
(AN,"A 'bovine' aortic arch is a common variant in which:","The innominate and left common carotid arteries share a common origin",["There are four arch branches","The arch is on the right","The subclavian is absent"],"It is usually harmless.","C"),
(AN,"The superior vena cava is formed by the union of the:","Right and left brachiocephalic veins",["Hepatic veins","Pulmonary veins","Internal jugular veins only"],"It enters the RA at its upper back part.","F"),
(AN,"The azygos vein drains into the:","Superior vena cava",["Inferior vena cava","Right atrium directly","Pulmonary artery"],"In azygos continuation of the IVC, the azygos is enlarged.","C"),
(AN,"The left atrial appendage lies close to the:","Left upper pulmonary vein",["Right upper pulmonary vein","Superior vena cava","Tricuspid valve"],"The ridge between them is the Coumadin ridge.","F"),
(AN,"The transverse pericardial sinus lies:","Behind the aorta and pulmonary artery, in front of the atria",["Behind the left atrium","Below the IVC","Inside the LV"],"Fluid here can mimic a mass near the aortic root on TEE.","C"),
(AN,"The oblique pericardial sinus lies:","Behind the left atrium, between the pulmonary veins",["In front of the RV","Around the aortic arch","Inside the RA"],"A localized effusion here can compress the LA.","C"),
(AN,"The 'crux' of the heart is where:","The atrial and ventricular septa meet the AV grooves on the back of the heart",["The aorta meets the PA","The SVC enters the RA","The apex touches the chest wall"],"The PDA usually arises near the crux.","C"),
(AN,"The esophagus lies directly behind the:","Left atrium",["Right ventricle","Aortic arch only","Right atrium"],"A very large LA can indent the esophagus.","F"),
(AN,"Normal adult heart weight is about:","250 to 350 grams",["50 grams","1,000 grams","2 kilograms"],"Echo LV mass is compared with indexed normal values.","F"),
# --- Atrial anatomy ---
(AN,"The pectinate muscles are found in:","Both atrial appendages and the right atrial free wall",["The LV only","The aortic root","The pulmonary veins"],"They give the appendages their ridged appearance.","F"),
(AN,"The smooth posterior part of the right atrium, where the venae cavae enter, is called the:","Sinus venarum",["Infundibulum","Fossa ovalis","Moderator band"],"It is separated from the trabeculated RA by the crista terminalis.","C"),
(AN,"The interatrial septum is thinnest at the:","Fossa ovalis",["Upper septum","Lower septum near the AV valves","Coronary sinus"],"Echo dropout is common here in apical views.","F"),
# --- Physiology: pressure-volume, energetics ---
(PH,"On a pressure-volume loop, the width of the loop represents:","Stroke volume",["Heart rate","Blood pressure","Ejection time"],"The area inside the loop is stroke work.","C"),
(PH,"Increased contractility shifts the end-systolic pressure-volume relationship:","Upward and to the left (steeper)",["Down and to the right","No change","Only in diastole"],"The ventricle empties more for a given pressure.","C"),
(PH,"According to Laplace's law, LV wall stress increases with:","Higher pressure and larger radius, and decreases with thicker walls",["Thicker walls","Lower pressure","Smaller radius only"],"Wall stress = pressure × radius ÷ (2 × wall thickness). Hypertrophy is the heart's way of reducing wall stress.","C"),
(PH,"The main determinants of myocardial oxygen demand are:","Heart rate, contractility and wall stress",["Valve area only","Blood glucose","Pericardial thickness"],"Stress testing increases all three to unmask ischemia.","F"),
(PH,"Coronary perfusion pressure for the LV is approximately:","Aortic diastolic pressure minus LV end-diastolic pressure",["Systolic pressure minus diastolic pressure","RA pressure minus LV pressure","Mean arterial pressure only"],"Low diastolic pressure (such as severe AR) or high LVEDP reduces coronary flow.","C"),
(PH,"Coronary autoregulation means:","Coronary flow stays fairly constant over a range of perfusion pressures",["Coronary flow always matches blood pressure exactly","Coronaries cannot dilate","Flow only occurs in systole"],"Beyond severe stenosis, autoregulation is exhausted.","C"),
(PH,"The three functions of the left atrium are:","Reservoir, conduit and booster pump",["Pump, valve and filter","Reservoir only","Filter, conduit and sensor"],"LA strain can measure each phase.","F"),
(PH,"The atrial 'kick' contributes about what share of LV filling in healthy adults?","About 20% to 30%",["About 80%","About 50%","None"],"It becomes more important with age and impaired relaxation; loss of it in AF can cause symptoms.","F"),
(PH,"The rapid ejection phase occurs:","Early in systole, just after the aortic valve opens",["At end-diastole","During isovolumic relaxation","During atrial systole"],"About two-thirds of the stroke volume is ejected in this phase.","F"),
(PH,"Stroke work is best described as:","The work the ventricle does to eject a stroke volume against pressure",["The number of beats per minute","Only the stroke volume","The size of the ventricle"],"It is the area inside the pressure-volume loop.","C"),
# --- Neurohormonal and reflexes ---
(PH,"The baroreceptor reflex responds to a sudden fall in blood pressure by:","Increasing heart rate and constricting blood vessels",["Slowing the heart","Dilating blood vessels","Stopping breathing"],"Baroreceptors are in the carotid sinus and aortic arch.","F"),
(PH,"The renin-angiotensin-aldosterone system, when activated, causes:","Vasoconstriction and salt and water retention",["Vasodilation and diuresis","Lower heart rate","Bradycardia only"],"Chronic activation worsens heart failure; ACE inhibitors block it.","F"),
(PH,"Natriuretic peptides (ANP and BNP) are released when the heart is stretched and cause:","Sodium and water excretion and vasodilation",["Salt retention","Vasoconstriction","Increased renin"],"They counterbalance the renin-angiotensin system.","F"),
(PH,"Standing up from lying down immediately causes:","A fall in venous return and preload, with a reflex rise in heart rate",["Increased preload","Lower heart rate","No change"],"Standing increases LVOT obstruction in HCM.","F"),
(PH,"During the strain phase of the Valsalva maneuver:","Venous return falls, so preload and stroke volume fall",["Venous return rises","Heart rate falls immediately","Stroke volume rises"],"On release, venous return surges back, briefly raising right-sided filling.","F"),
(PH,"Squatting from standing causes:","Increased venous return and afterload",["Decreased venous return","Decreased afterload","No change"],"It reduces HCM obstruction and its murmur.","F"),
(PH,"Passive leg raise during echo is used to:","Briefly increase preload and test fluid responsiveness",["Lower preload","Raise afterload only","Slow the heart"],"A rise in LVOT VTI of more than about 10% to 15% suggests the patient would respond to fluids.","C"),
(PH,"Normal ventricular interdependence means that:","Changes in filling of one ventricle affect the other through the shared septum and pericardium",["The ventricles work completely independently","Only the RV affects the LV","It occurs only in disease"],"It is exaggerated in tamponade and constriction.","F"),
(PH,"During normal inspiration, mitral inflow E velocity:","Falls slightly (usually by less than about 10% to 15%)",["Rises sharply","Doesn't exist","Falls by over 50%"],"Larger variation suggests tamponade or constriction.","C"),
# --- Exercise and aging ---
(PH,"During normal exercise, LV end-systolic volume:","Decreases as contractility rises",["Increases","Stays the same","Doubles"],"EF rises. An increase in ESV with exercise is abnormal.","F"),
(PH,"During normal dynamic exercise, blood pressure changes how?","Systolic rises; diastolic stays about the same or falls slightly",["Both fall","Systolic falls","Diastolic rises sharply"],"A drop in systolic pressure with exercise is an abnormal, high-risk finding.","F"),
(PH,"Normal aging of the heart often shows:","A slightly thicker basal septum (sigmoid septum), stiffer LV and reduced e′",["A thinner LV and higher e′","A smaller aortic root","Faster relaxation"],"A sigmoid septum can rarely cause mild LVOT acceleration.","F"),
(PH,"Maximum heart rate declines with age, which is why target heart rate is based on:","220 minus age",["Weight","Height","Blood pressure"],"For a 40-year-old the predicted maximum is about 180 beats per minute.","F"),
(PH,"Cardiac reserve is:","The heart's ability to increase output above resting levels",["Resting heart rate","Blood stored in the LA","The size of the pericardium"],"Reserve is reduced in heart failure, limiting exercise.","F"),
(PH,"An athlete's heart typically shows:","Balanced enlargement of chambers, normal or supernormal diastolic function and a low resting heart rate",["Small chambers with impaired relaxation","Asymmetric septal hypertrophy","Reduced EF at rest always"],"These changes are physiologic adaptations.","F"),
# --- Electrophysiology ---
(PH,"Myocardial contraction is triggered when:","Calcium enters the cell and is released from internal stores",["Potassium leaves the heart","Sodium is blocked","Oxygen enters the cell"],"This is called excitation-contraction coupling.","C"),
(PH,"The AV node normally delays conduction so that:","The atria finish contracting before the ventricles contract",["The ventricles contract first","The heart rate doubles","The valves stay open"],"This delay appears as the PR interval.","F"),
(PH,"The refractory period of heart muscle prevents:","Sustained (tetanic) contraction, allowing the heart to relax and fill",["Any contraction","Relaxation","Conduction"],"Skeletal muscle can sustain contraction; the heart cannot.","C"),
(PH,"The normal PR interval is about:","0.12 to 0.20 seconds",["0.01 seconds","0.5 seconds","1 second"],"A long PR delays ventricular contraction and can fuse the E and A waves.","C"),
(PH,"A long PR interval (first-degree AV block) can affect mitral inflow by:","Causing E and A waves to fuse or the A wave to come early, sometimes with diastolic MR",["Removing the E wave","Doubling the heart rate","Causing aortic stenosis"],"Atrial contraction happens too early relative to ventricular contraction.","C"),
(PH,"Normal pulmonary artery diastolic pressure is about:","8 to 15 mmHg",["40 mmHg","1 mmHg","80 mmHg"],"It normally approximates the pulmonary capillary wedge pressure.","C"),
(PH,"Pulmonary capillary wedge pressure estimates:","Left atrial pressure",["Right atrial pressure","Aortic pressure","RV systolic pressure"],"Echo estimates it non-invasively with E/e′ and other measures.","F"),
(PH,"Cardiac output is distributed at rest roughly so that:","The kidneys, liver and gut together receive a large share, with smaller shares to the brain and heart",["The heart receives half","The skin receives most","The lungs receive none"],"The heart receives about 5% of cardiac output; during exercise, muscles receive most.","C"),
(PH,"Mitral annular descent toward the apex during systole helps:","Fill the left atrium by acting like a piston",["Close the aortic valve","Lower heart rate","Increase afterload"],"It contributes to the systolic pulmonary venous S wave.","C"),
(PH,"Normal mixed venous oxygen saturation (pulmonary artery blood) is about:","70% to 75%",["98%","40%","90% to 100%"],"Low values suggest low cardiac output or high oxygen use.","C"),
]
